const input = $input.first().json;

console.log('\n🔍 АНАЛИЗ ОТВЕТА ОТ INSTAGRAM:');
console.log('   Input type:', typeof input);
console.log('   Input keys:', input ? Object.keys(input) : 'null');
console.log('   Has data:', input && input.data ? 'yes' : 'no');
console.log('   Data length:', input && input.data ? input.data.length : 0);
console.log('   Has paging:', input && input.paging ? 'yes' : 'no');

if (!input) {
  console.log('❌ Нет ответа от Instagram API');
  return { json: { skip: true, reason: 'no_response' } };
}

if (!input.data || input.data.length === 0) {
  console.log('⚠️ Нет постов в ответе от Instagram');
  console.log('   Full response:', JSON.stringify(input).substring(0, 500));
  return { json: { skip: true, reason: 'no_posts' } };
}

const posts = input.data;
console.log(`\n✅ Получено постов: ${posts.length}`);

// Показываем первые несколько постов для отладки
if (posts.length > 0) {
  console.log('\n📋 Примеры постов:');
  posts.slice(0, 3).forEach((post, idx) => {
    const date = post.timestamp ? new Date(post.timestamp).toISOString().split('T')[0] : 'нет даты';
    console.log(`   ${idx + 1}. ID: ${post.id}, Дата: ${date}, Тип: ${post.media_type || 'unknown'}`);
  });
}

// Проверяем пагинацию
if (input.paging && input.paging.next) {
  console.log('\n⚠️ Есть еще посты! URL следующей страницы:', input.paging.next.substring(0, 100) + '...');
  console.log('   Для загрузки всех постов нужно добавить пагинацию');
}

// Возвращаем массив постов для дальнейшей обработки
return posts.map(post => ({
  json: {
    post_id: post.id,
    caption: post.caption || '',
    media_type: post.media_type,
    media_url: post.media_url,
    posted_at: post.timestamp,
    permalink: post.permalink
  }
}));

const postData = $input.first().json;
const insights = $input.last().json;

function extractMetric(data, metricName) {
  if (!data || !data.data || !Array.isArray(data.data)) return 0;
  const metric = data.data.find(m => m.name === metricName);
  return metric?.values?.[0]?.value || 0;
}

const reach = extractMetric(insights, 'reach');

// Обрабатываем posted_at - конвертируем в правильный формат
let postedAt = postData.posted_at;
if (!postedAt || postedAt === '') {
  postedAt = new Date().toISOString();
  console.log(`⚠️ Post ${postData.post_id}: нет timestamp, используем текущую дату`);
} else {
  // Убеждаемся, что это валидная дата
  try {
    const date = new Date(postedAt);
    if (isNaN(date.getTime())) {
      console.log(`⚠️ Post ${postData.post_id}: невалидная дата ${postedAt}, используем текущую`);
      postedAt = new Date().toISOString();
    } else {
      postedAt = date.toISOString();
    }
  } catch (e) {
    console.log(`⚠️ Post ${postData.post_id}: ошибка парсинга даты ${postedAt}:`, e.message);
    postedAt = new Date().toISOString();
  }
}

// Проверяем, попадает ли пост в период 1-22 января
const postDate = new Date(postedAt);
const periodStart = new Date('2026-01-01T00:00:00.000Z');
const periodEnd = new Date('2026-01-22T23:59:59.999Z');
const isInPeriod = postDate >= periodStart && postDate <= periodEnd;

const result = {
  post_id: postData.post_id,
  caption: postData.caption || '',
  media_type: postData.media_type || 'UNKNOWN',
  media_url: postData.media_url || '',
  posted_at: postedAt,
  permalink: postData.permalink || '',
  reach: reach,
  impressions: extractMetric(insights, 'impressions') || reach, // Используем reach как fallback
  likes: extractMetric(insights, 'likes'),
  comments: extractMetric(insights, 'comments'),
  shares: extractMetric(insights, 'shares'),
  saves: extractMetric(insights, 'saved'),
  // Лиды и выручка - по умолчанию 0 (можно считать отдельно позже)
  leads_count: 0,
  paid_leads: 0,
  revenue: 0
};

const dateStr = postDate.toISOString().split('T')[0];
const periodStatus = isInPeriod ? '✅ В ПЕРИОДЕ 1-22 янв' : '❌ ВНЕ ПЕРИОДА';
console.log(`✅ Post ${result.post_id}: Дата ${dateStr} | ${periodStatus} | ${result.impressions} показов, ${result.reach} охват, ${result.likes} лайков`);

return { json: result };

const items = $input.all();
const successCount = items.length;

console.log(`\n✅ УСПЕШНО СОХРАНЕНО: ${successCount} постов\n`);

return {
  json: {
    success: true,
    posts_processed: successCount,
    timestamp: new Date().toISOString()
  }
};
